import { fireEvent, render, screen } from '@testing-library/react';
import React from 'react';
import Quantifier from './Quantifier';

const mockedOnValueChange = jest.fn();
const mockedOnClickMinusButton = jest.fn();
const mockedOnClickPlusButton = jest.fn();
const mockedOnChange = jest.fn();

describe('Quantifier', () => {
  it('should render without crashing', () => {
    render(<Quantifier data-testid="input-quantifier" />);
    const input = screen.getByTestId('input-quantifier');
    expect(input.value).toBe('0');
  });

  it('should disable minus button when value is less or equal to min', () => {
    render(<Quantifier size="medium" />);
    const minusButton = screen.getAllByRole('button')[0];
    expect(minusButton.disabled).toBe(true);
  });

  it('should trigger onClickMinusButton and onValueChange when user click on MinusButton', () => {
    render(
      <Quantifier
        size="medium"
        onValueChange={mockedOnValueChange}
        onClickMinusButton={mockedOnClickMinusButton}
        defaultValue="1"
      />
    );
    const minusButton = screen.getAllByRole('button')[0];
    fireEvent.click(minusButton);
    expect(mockedOnClickMinusButton).toHaveBeenCalled();
    expect(mockedOnValueChange).toHaveBeenCalled();
  });

  it('should disable plus button when value is more or equal to max', () => {
    render(<Quantifier size="medium" max={1} />);
    const plusButton = screen.getAllByRole('button')[1];
    fireEvent.click(plusButton);
    expect(plusButton.disabled).toBe(true);
  });

  it('should trigger onClickMinusButton and onValueChange when user click on PlusButton', () => {
    render(
      <Quantifier
        size="medium"
        onValueChange={mockedOnValueChange}
        onClickPlusButton={mockedOnClickPlusButton}
      />
    );
    const plusButton = screen.getAllByRole('button')[1];
    fireEvent.click(plusButton);
    expect(mockedOnClickPlusButton).toHaveBeenCalled();
    expect(mockedOnValueChange).toHaveBeenCalled();
  });

  it('should round input value when user types a decimal number', () => {
    render(<Quantifier data-testid="input-quantifier" />);
    const input = screen.getByTestId('input-quantifier');
    fireEvent.change(input, { target: { value: '3.9' } });
    expect(input.value).toBe('4');
  });

  it('should trigger onChange when user change input value', () => {
    render(<Quantifier data-testid="input-quantifier" onChange={mockedOnChange} />);
    const input = screen.getByTestId('input-quantifier');
    fireEvent.change(input, { target: { value: '2' } });
    expect(mockedOnChange).toHaveBeenCalled();
  });

  it('should trigger onValueChange when user change input value', () => {
    const mockedValue = 0;
    render(
      <Quantifier
        data-testid="input-quantifier"
        value={mockedValue}
        onValueChange={mockedOnValueChange}
        onChange={mockedOnChange}
      />
    );
    const input = screen.getByTestId('input-quantifier');
    fireEvent.change(input, { target: { value: '2' } });
    expect(mockedOnChange).toHaveBeenCalled();
    expect(mockedOnValueChange).toHaveBeenCalled();
  });
});
